function QueryEditor({ query, setQuery }) {
  return <div className="editor-code"><div className="line-numbers">{query.split('\n').map((_, index) => <span key={index}>{index + 1}</span>)}</div><div className="code-lines"><textarea className="query-textarea" aria-label="OQL query" value={query} onChange={(event) => setQuery(event.target.value)} spellCheck="false" /></div></div>
}

function Logo() {
  return <div className="brand-lockup"><div className="brand-mark"><span>R</span><i /></div><div><div className="brand-name">Rustty<span>Object</span></div><div className="brand-caption">OBJECT STORAGE</div></div></div>
}

function StatusPill({ children, tone = 'neutral', dot = true }) {
  return <span className={`status-pill ${tone}`}>{dot && <span className="status-dot" />}{children}</span>
}

function MetricCard({ label, value, detail, trend, direction = 'up', icon }) {
  return <article className="metric-card">
    <div className="metric-card-top"><span className="metric-label">{label}</span><span className="metric-icon"><Icon name={icon} size={17} /></span></div>
    <div className="metric-value">{value}</div>
    <div className="metric-bottom"><span>{detail}</span><span className={`trend ${direction}`}><Icon name={direction === 'up' ? 'arrowUp' : 'arrowDown'} size={13} />{trend}</span></div>
  </article>
}

function StorageChart() {
  const bars = [42, 48, 44, 55, 49, 62, 58, 67, 64, 71, 68, 78, 74, 82, 76, 88, 83, 91, 88, 96, 92, 100, 95, 100]
  return <div className="chart-wrap">
    <div className="chart-stats"><div><span className="chart-number">8.42</span><span className="chart-unit">GB used</span></div><div className="chart-legend"><span className="legend-swatch" /> storage usage</div></div>
    <div className="chart-area">
      <div className="chart-y-labels"><span>10 GB</span><span>7.5 GB</span><span>5 GB</span><span>2.5 GB</span><span>0 GB</span></div>
      <div className="chart-plot">
        <div className="chart-grid-lines"><span /><span /><span /><span /><span /></div>
        <div className="bar-row">{bars.map((height, index) => <span key={index} className={`usage-bar ${index > 20 ? 'highlight' : ''}`} style={{ height: `${height}%` }} />)}</div>
      </div>
    </div>
    <div className="chart-x-labels"><span>Jul 21</span><span>Jul 28</span><span>Aug 04</span><span>Aug 11</span><span>Aug 17</span></div>
  </div>
}

function BucketIcon({ tone }) {
  return <span className={`bucket-icon ${tone}`}><Icon name="box" size={19} /></span>
}

function ObjectIcon({ type }) {
  return <span className={`object-icon ${type === 'video' ? 'pink' : type === 'image' ? 'green' : 'orange'}`}><Icon name={type} size={17} /></span>
}

function FeatureHeader({ eyebrow, title, subtitle, children }) {
  return <div className="page-heading feature-heading"><div><div className="eyebrow"><span className="eyebrow-line" /> {eyebrow}</div><h1>{title}</h1><p>{subtitle}</p></div><div className="heading-actions">{children}</div></div>
}

function Toggle({ checked, onChange }) {
  return <button className={`toggle ${checked ? 'on' : ''}`} onClick={() => onChange(!checked)} aria-label={checked ? 'Disable setting' : 'Enable setting'}><span /></button>
}

function FeaturePage({ activeNav, setActiveNav, setShowUpload, query, setQuery, runQuery, queryRan }) {
  const [selectedBucket, setSelectedBucket] = useState(bucketData[0].name)
  const [bucketTab, setBucketTab] = useState('Objects')
  const [bucketSearch, setBucketSearch] = useState('')
  const [showBucketModal, setShowBucketModal] = useState(false)
  const [oqlTab, setOqlTab] = useState('Console')
  const [repoFilter, setRepoFilter] = useState('All repositories')
  const [showRepoModal, setShowRepoModal] = useState(false)
  const [activityFilter, setActivityFilter] = useState('All events')
  const [settingsSection, setSettingsSection] = useState('Workspace')
  const [autoSync, setAutoSync] = useState(true)
  const [protectMain, setProtectMain] = useState(true)
  const [publicLinks, setPublicLinks] = useState(false)
  const [saved, setSaved] = useState(false)

  const currentBucket = bucketData.find((bucket) => bucket.name === selectedBucket) || bucketData[0]
  const bucketObjects = objectData.filter((object) => object.bucket === selectedBucket && `${object.name} ${object.type}`.toLowerCase().includes(bucketSearch.toLowerCase()))
  const visibleRepos = repositoryData.filter((repo) => repoFilter === 'All repositories' || repo.status === repoFilter)
  const visibleActivity = activityData.filter((event) => activityFilter === 'All events' || event.type === activityFilter)

  if (activeNav === 'Buckets') return <div className="feature-page">
    <FeatureHeader eyebrow="WORKSPACE / BUCKETS" title="Buckets" subtitle="Isolated storage spaces for every class of object."><button className="secondary-button"><Icon name="filter" size={15} /> Filter</button><button className="primary-button" onClick={() => setShowBucketModal(true)}><Icon name="plus" size={17} /> New bucket</button></FeatureHeader>
    <div className="feature-stats"><div className="mini-stat"><span>Total buckets</span><strong>03</strong><small>all systems nominal</small></div><div className="mini-stat"><span>Total objects</span><strong>23,842</strong><small className="positive">↑ 8.4% this month</small></div><div className="mini-stat"><span>Storage used</span><strong>8.42 GB</strong><small>of 50 GB included</small></div><div className="mini-stat"><span>Avg. sync time</span><strong>42 ms</strong><small className="positive">↓ 12 ms faster</small></div></div>
    <div className="bucket-browser"><aside className="panel bucket-directory"><div className="directory-head"><div><h2>All buckets</h2><p>3 storage spaces</p></div><button className="square-button" onClick={() => setShowBucketModal(true)}><Icon name="plus" size={16} /></button></div><div className="directory-search"><Icon name="search" size={15} /><input placeholder="Find a bucket" /></div><div className="directory-list">{bucketData.map((bucket) => <button key={bucket.name} className={`directory-item ${selectedBucket === bucket.name ? 'active' : ''}`} onClick={() => setSelectedBucket(bucket.name)}><BucketIcon tone={bucket.tone} /><span><strong>{bucket.name}</strong><small>{bucket.objects} objects · {bucket.size}</small></span><Icon name="chevron" size={14} /></button>)}</div><button className="directory-create" onClick={() => setShowBucketModal(true)}><Icon name="plus" size={15} /> Create a bucket</button></aside><div className="bucket-detail"><div className="panel bucket-detail-card"><div className="bucket-detail-top"><div className="bucket-detail-name"><BucketIcon tone={currentBucket.tone} /><div><div className="detail-title-row"><h2>{currentBucket.name}</h2><StatusPill tone={currentBucket.status === 'Synced' ? 'success' : 'warning'}>{currentBucket.status}</StatusPill></div><p>{currentBucket.description} · GitHub branch <strong>main</strong></p></div></div><div className="detail-actions"><button className="secondary-button"><Icon name="settings" size={15} /> Configure</button><button className="square-button"><Icon name="more" size={17} /></button></div></div><div className="bucket-detail-metrics"><div><span>Objects</span><strong>{currentBucket.objects}</strong></div><div><span>Storage used</span><strong>{currentBucket.size}</strong></div><div><span>Last activity</span><strong>{currentBucket.updated}</strong></div><div><span>Access</span><strong>Private</strong></div></div><div className="detail-tabs">{['Objects', 'Settings', 'Permissions'].map((tab) => <button key={tab} className={bucketTab === tab ? 'active' : ''} onClick={() => setBucketTab(tab)}>{tab}{tab === 'Objects' && <em>{currentBucket.objects}</em>}</button>)}</div></div>{bucketTab === 'Objects' && <div className="panel object-index-card"><div className="table-heading"><div><h2>Object index</h2><p>Files currently stored in {currentBucket.name}</p></div><div className="object-controls"><div className="inline-search"><Icon name="search" size={14} /><input value={bucketSearch} onChange={(event) => setBucketSearch(event.target.value)} placeholder="Search objects" /></div><button className="primary-button" onClick={() => setShowUpload(true)}><Icon name="upload" size={15} /> Upload</button></div></div><div className="table-scroll"><table><thead><tr><th>Object</th><th>Type</th><th>Size</th><th>Updated</th><th>Hash</th><th /></tr></thead><tbody>{bucketObjects.map((object) => <tr key={object.name}><td><div className="object-cell"><ObjectIcon type={object.icon} /><span><strong>{object.name}</strong><small>/{object.name}</small></span></div></td><td><span className="type-label">{object.type}</span></td><td className="mono-cell">{object.size}</td><td className="muted-cell">{object.updated}</td><td className="mono-cell">{object.hash}</td><td><button className="row-more"><Icon name="more" size={17} /></button></td></tr>)}{bucketObjects.length === 0 && <tr><td colSpan="6" className="empty-state">No objects match this search.</td></tr>}</tbody></table></div><div className="index-footer"><span>Showing {bucketObjects.length} of {currentBucket.objects} objects</span><div><button className="pagination-button"><Icon name="chevron" size={13} className="flip-horizontal" /></button><button className="pagination-button"><Icon name="chevron" size={13} /></button></div></div></div>}{bucketTab !== 'Objects' && <div className="panel settings-card"><div className="settings-card-heading"><div><h2>{bucketTab}</h2><p>Manage {bucketTab.toLowerCase()} for {currentBucket.name}.</p></div><StatusPill tone="success">Configured</StatusPill></div><div className="bucket-setting-list"><div><span><strong>Repository path</strong><small>rusttyobject/storage/{currentBucket.name}</small></span><button className="copy-setting"><Icon name="copy" size={14} /> Copy</button></div><div><span><strong>Default access</strong><small>Only members of rusttyobject can read and write objects.</small></span><StatusPill tone="dark">Private</StatusPill></div><div><span><strong>Retention policy</strong><small>Objects are retained until explicitly deleted.</small></span><span className="setting-value">Forever <Icon name="chevron" size={13} /></span></div></div></div>}</div></div>
    {showBucketModal && <div className="modal-backdrop" onClick={() => setShowBucketModal(false)}><div className="upload-modal feature-modal" onClick={(event) => event.stopPropagation()}><div className="modal-head"><div><div className="modal-icon"><Icon name="box" size={20} /></div><h2>Create bucket</h2><p>Set up an isolated namespace for your objects.</p></div><button className="modal-close" onClick={() => setShowBucketModal(false)}><Icon name="close" size={18} /></button></div><label className="modal-label">Bucket name<input className="modal-input" placeholder="e.g. customer-uploads" /></label><label className="modal-label">Description<input className="modal-input" placeholder="What will this bucket store?" /></label><label className="modal-label">Visibility<select><option>Private · workspace members only</option><option>Public · anyone with a link</option></select></label><div className="modal-actions"><button className="secondary-button" onClick={() => setShowBucketModal(false)}>Cancel</button><button className="primary-button" onClick={() => setShowBucketModal(false)}><Icon name="plus" size={16} /> Create bucket</button></div></div></div>}
  </div>

  if (activeNav === 'OQL terminal') return <div className="feature-page oql-page">
    <FeatureHeader eyebrow="WORKSPACE / QUERY" title="OQL terminal" subtitle="Explore your object index with Object Query Language."><button className="secondary-button"><Icon name="clock" size={16} /> Query history</button><button className="primary-button" onClick={() => setQuery(queryExamples[0])}><Icon name="plus" size={17} /> New query</button></FeatureHeader>
    <div className="oql-toolbar"><div className="oql-tabs">{['Console', 'Saved queries'].map((tab) => <button className={oqlTab === tab ? 'active' : ''} key={tab} onClick={() => setOqlTab(tab)}>{tab}{tab === 'Saved queries' && <em>04</em>}</button>)}</div><div className="oql-shortcuts"><span><kbd>⌘</kbd><kbd>↵</kbd> Run</span><span><kbd>⌘</kbd><kbd>K</kbd> Command menu</span></div></div>
    {oqlTab === 'Console' ? <div className="oql-layout"><aside className="panel oql-explorer"><div className="explorer-head"><h2>Schema explorer</h2><button className="more-button"><Icon name="more" size={17} /></button></div><p className="explorer-caption">Available fields across objects</p><div className="schema-group"><span className="schema-group-title"><Icon name="down" size={13} /> objects</span><div className="schema-field"><span className="field-type string">Aa</span>name</div><div className="schema-field"><span className="field-type string">Aa</span>bucket</div><div className="schema-field"><span className="field-type string">Aa</span>type</div><div className="schema-field"><span className="field-type number">#</span>size</div><div className="schema-field"><span className="field-type date">◷</span>updated_at</div><div className="schema-field"><span className="field-type string">Aa</span>hash</div></div><div className="schema-divider" /><div className="history-head"><span>Recent queries</span><button>Clear</button></div><div className="history-list"><button onClick={() => setQuery(queryExamples[0])}><Icon name="clock" size={13} /><span>SELECT * FROM media...</span><small>42ms</small></button><button onClick={() => setQuery(queryExamples[1])}><Icon name="clock" size={13} /><span>FIND type = 'video'...</span><small>18ms</small></button><button onClick={() => setQuery(queryExamples[2])}><Icon name="clock" size={13} /><span>COUNT objects WHERE...</span><small>7ms</small></button></div></aside><div className="oql-workspace"><div className="console-shell full-console"><div className="console-top"><div className="console-title"><span className="terminal-icon"><Icon name="terminal" size={17} /></span><div><h2>query.oql</h2><p>Unsaved query · main workspace</p></div></div><div className="console-top-right"><StatusPill tone="dark">OQL v1.4</StatusPill><button className="console-expand"><Icon name="copy" size={14} /> Save query</button></div></div><div className="console-body"><div className="console-editor"><div className="editor-toolbar"><div className="editor-tab"><span className="tab-dot" /> query.oql <Icon name="close" size={12} /></div><span className="editor-hint">UTF-8</span></div><QueryEditor query={query} setQuery={setQuery} /><div className="editor-actions"><button className="run-button" onClick={runQuery}><Icon name="play" size={13} /> Run query <kbd>⌘ ↵</kbd></button><button className="copy-button" onClick={() => navigator.clipboard?.writeText(query)}><Icon name="copy" size={14} /> Copy</button></div></div><div className="console-output"><div className="output-head"><span>OUTPUT</span><span className="output-time">{queryRan ? 'Query completed in 42ms' : 'Ready'}</span></div>{queryRan ? <div className="query-result"><div className="result-success"><Icon name="check" size={14} /> 4 objects returned</div><div className="result-row"><span>hero-loop.mp4</span><span>18.4 MB</span></div><div className="result-row"><span>product-tour.mp4</span><span>32.1 MB</span></div></div> : <div className="output-placeholder"><span className="prompt">›</span><span>Run a query to see results here</span></div>}</div></div></div><div className="query-suggestions"><span>Try an example</span>{queryExamples.map((example, index) => <button key={example} onClick={() => setQuery(example)} className={query === example ? 'active' : ''}><span>0{index + 1}</span>{example}</button>)}</div></div>{queryRan && <div className="panel results-card"><div className="results-card-head"><div><h2>Query result</h2><p>4 rows returned · 42ms · scanned 2,904 objects</p></div><div><button className="secondary-button"><Icon name="download" size={14} /> Export CSV</button></div></div><div className="table-scroll"><table><thead><tr><th>name</th><th>bucket</th><th>type</th><th>size</th><th>updated_at</th></tr></thead><tbody>{objectData.slice(0, 4).map((object) => <tr key={object.name}><td className="result-name">{object.name}</td><td className="bucket-name-cell">{object.bucket}</td><td><span className="type-label">{object.type}</span></td><td className="mono-cell">{object.size}</td><td className="muted-cell">{object.updated}</td></tr>)}</tbody></table></div></div>}</div> : <div className="panel saved-query-list"><div className="saved-query-heading"><div><h2>Saved queries</h2><p>Reusable queries shared with your workspace.</p></div><button className="primary-button" onClick={() => setOqlTab('Console')}><Icon name="plus" size={15} /> Save current query</button></div>{['Latest videos by bucket', 'Large objects over 10 MB', 'Recently changed assets', 'Storage by content type'].map((name, index) => <div className="saved-query-row" key={name}><span className="saved-query-icon"><Icon name="terminal" size={15} /></span><span><strong>{name}</strong><small>{queryExamples[index % queryExamples.length]}</small></span><span className="saved-owner">Alex Smith · {index + 1}d ago</span><button className="row-more"><Icon name="more" size={17} /></button></div>)}</div>}
  </div>

  if (activeNav === 'Repositories') return <div className="feature-page">
    <FeatureHeader eyebrow="WORKSPACE / GITHUB" title="Repositories" subtitle="GitHub sources connected to your object storage workspace."><button className="secondary-button"><Icon name="activity" size={15} /> Sync status</button><button className="primary-button" onClick={() => setShowRepoModal(true)}><Icon name="plus" size={17} /> Connect repository</button></FeatureHeader>
    <div className="repo-summary"><div className="repo-connection"><span className="github-large"><Icon name="github" size={23} /></span><div><span className="repo-overline">CONNECTED GITHUB ACCOUNT</span><strong>rusttyobject</strong><small>github.com/rusttyobject · 3 repositories connected</small></div><StatusPill tone="success">Connected</StatusPill><button className="secondary-button">Manage account</button></div><div className="repo-health"><div><span>Last sync</span><strong>just now</strong></div><div><span>Successful syncs</span><strong>99.98%</strong></div><div><span>Commits indexed</span><strong>14,892</strong></div></div></div>
    <div className="repository-panel panel"><div className="panel-heading table-heading"><div><h2>Connected repositories</h2><p>Each repository maps to one or more RusttyObject buckets.</p></div><div className="object-controls"><select value={repoFilter} onChange={(event) => setRepoFilter(event.target.value)}><option>All repositories</option><option>Synced</option><option>Syncing</option></select><button className="filter-button"><Icon name="filter" size={15} /> Filter</button></div></div><div className="table-scroll"><table><thead><tr><th>Repository</th><th>Branch</th><th>Objects</th><th>Storage</th><th>Last commit</th><th>Status</th><th /></tr></thead><tbody>{visibleRepos.map((repo) => <tr key={repo.name}><td><div className="repository-cell"><span className={`repo-icon ${repo.tone}`}><Icon name="github" size={16} /></span><span><strong>{repo.owner}/{repo.name}</strong><small>github.com/{repo.owner}/{repo.name}</small></span></div></td><td><span className="branch-label"><Icon name="branch" size={13} /> {repo.branch}</span></td><td className="mono-cell">{repo.objects}</td><td className="mono-cell">{repo.size}</td><td><span className="commit-label"><code>{repo.commit}</code> · {repo.updated}</span></td><td><StatusPill tone={repo.status === 'Synced' ? 'success' : 'warning'}>{repo.status}</StatusPill></td><td><button className="row-more"><Icon name="more" size={17} /></button></td></tr>)}</tbody></table></div></div>
    <div className="repo-bottom-grid"><div className="panel branch-card"><div className="panel-heading"><div><h2>Branch mapping</h2><p>How GitHub branches map to buckets</p></div><button className="more-button"><Icon name="more" size={17} /></button></div><div className="branch-map"><div className="branch-node"><span className="repo-icon green"><Icon name="github" size={14} /></span><strong>main</strong><small>storage root</small></div><div className="branch-line" /><div className="branch-node"><BucketIcon tone="violet" /><strong>media-production</strong><small>12,428 objects</small></div><div className="branch-node"><BucketIcon tone="blue" /><strong>design-assets</strong><small>8,392 objects</small></div></div></div><div className="panel webhook-card"><div className="panel-heading"><div><h2>Webhook status</h2><p>Real-time event delivery</p></div><StatusPill tone="success">Healthy</StatusPill></div><div className="webhook-url"><span className="webhook-dot" /><code>api.rusttyobject.dev/hooks/github</code><button className="copy-setting"><Icon name="copy" size={13} /></button></div><div className="webhook-foot"><span>Last delivery <strong>14 seconds ago</strong></span><span>1,284 events <Icon name="arrowUp" size={12} /></span></div></div></div>
    {showRepoModal && <div className="modal-backdrop" onClick={() => setShowRepoModal(false)}><div className="upload-modal feature-modal" onClick={(event) => event.stopPropagation()}><div className="modal-head"><div><div className="modal-icon github-modal-icon"><Icon name="github" size={20} /></div><h2>Connect repository</h2><p>Choose a GitHub repository to index.</p></div><button className="modal-close" onClick={() => setShowRepoModal(false)}><Icon name="close" size={18} /></button></div><label className="modal-label">Repository<select><option>rusttyobject / website</option><option>rusttyobject / media-archive</option><option>rusttyobject / incoming-drops</option></select></label><label className="modal-label">Default bucket<select><option>incoming-drops</option><option>media-production</option><option>design-assets</option></select></label><div className="sync-choice"><span><strong>Start initial sync</strong><small>Index existing files as soon as the connection is created.</small></span><Toggle checked={true} onChange={() => {}} /></div><div className="modal-actions"><button className="secondary-button" onClick={() => setShowRepoModal(false)}>Cancel</button><button className="primary-button" onClick={() => setShowRepoModal(false)}><Icon name="branch" size={16} /> Connect repository</button></div></div></div>}
  </div>

  if (activeNav === 'Activity log') return <div className="feature-page">
    <FeatureHeader eyebrow="WORKSPACE / AUDIT" title="Activity log" subtitle="A complete timeline of changes across your storage workspace."><button className="secondary-button"><Icon name="download" size={15} /> Export log</button><button className="secondary-button"><Icon name="clock" size={15} /> Last 30 days <Icon name="down" size={13} /></button></FeatureHeader>
    <div className="activity-summary"><div className="mini-stat"><span>Total events</span><strong>1,284</strong><small>this month</small></div><div className="mini-stat"><span>Push events</span><strong>704</strong><small className="positive">↑ 18.2%</small></div><div className="mini-stat"><span>Pull events</span><strong>580</strong><small>across 3 repos</small></div><div className="mini-stat"><span>Active users</span><strong>08</strong><small>last 30 days</small></div></div>
    <div className="activity-layout"><div className="panel activity-log-card"><div className="activity-log-toolbar"><div><h2>Workspace events</h2><p>Showing the latest changes and sync operations</p></div><div className="activity-filters"><select value={activityFilter} onChange={(event) => setActivityFilter(event.target.value)}><option>All events</option><option>Push</option><option>Pull</option><option>Bucket</option><option>Delete</option><option>Policy</option></select><button className="filter-button"><Icon name="filter" size={15} /> Filters</button></div></div><div className="timeline">{visibleActivity.map((event, index) => <div className="timeline-item" key={`${event.action}-${index}`}><div className={`timeline-icon ${event.tone}`}><Icon name={event.icon} size={14} /></div><div className="timeline-content"><div><strong>{event.action}</strong><StatusPill tone="neutral" dot={false}>{event.type}</StatusPill></div><p>{event.detail}</p></div><time>{event.time}</time></div>)}{visibleActivity.length === 0 && <div className="empty-state">No events match this filter.</div>}</div><button className="load-more">Load older events <Icon name="down" size={14} /></button></div><aside className="activity-aside"><div className="panel activity-chart-card"><div className="panel-heading"><div><h2>Events by day</h2><p>Last 14 days</p></div><button className="more-button"><Icon name="more" size={17} /></button></div><div className="sparkline"><div className="sparkline-grid"><i /><i /><i /></div><svg viewBox="0 0 280 90" preserveAspectRatio="none"><path d="M0 72 C18 68, 25 51, 43 57 S68 68, 84 42 S109 32, 126 53 S148 64, 162 38 S181 56, 196 31 S213 41, 228 22 S253 37, 280 9" /></svg></div><div className="sparkline-labels"><span>Aug 04</span><span>Aug 10</span><span>Aug 17</span></div></div><div className="panel audit-note"><span className="note-icon"><Icon name="check" size={16} /></span><div><strong>Audit trail is healthy</strong><p>All GitHub webhook events are being recorded and verified.</p><button>View webhook details <Icon name="arrowUp" size={13} /></button></div></div></aside></div>
  </div>

  return <div className="feature-page settings-page">
    <FeatureHeader eyebrow="WORKSPACE / SETTINGS" title="Settings" subtitle="Control how RusttyObject connects, syncs, and serves your objects."><button className="secondary-button"><Icon name="external" size={15} /> Documentation</button><button className="primary-button" onClick={() => { setSaved(true); window.setTimeout(() => setSaved(false), 1800) }}>{saved ? <><Icon name="check" size={15} /> Saved</> : 'Save changes'}</button></FeatureHeader>
    <div className="settings-layout"><aside className="panel settings-nav"><div className="settings-nav-label">Configuration</div>{['Workspace', 'GitHub connection', 'Sync rules', 'Access & tokens', 'Usage & billing'].map((section) => <button key={section} className={settingsSection === section ? 'active' : ''} onClick={() => setSettingsSection(section)}><Icon name={section === 'Workspace' ? 'grid' : section === 'GitHub connection' ? 'github' : section === 'Sync rules' ? 'activity' : section === 'Access & tokens' ? 'settings' : 'box'} size={16} /><span>{section}</span><Icon name="chevron" size={13} /></button>)}<div className="settings-nav-bottom"><StatusPill tone="success">All systems operational</StatusPill><small>RusttyObject v0.8.2</small></div></aside><div className="settings-content"><div className="settings-section-heading"><div><span className="eyebrow compact-eyebrow">{settingsSection.toUpperCase()}</span><h2>{settingsSection}</h2><p>{settingsSection === 'Workspace' ? 'Basic identity and defaults for your storage workspace.' : 'Manage the configuration for this part of your workspace.'}</p></div></div>{settingsSection === 'Workspace' && <><div className="panel settings-card"><div className="settings-card-heading"><div><h2>Workspace identity</h2><p>How your workspace appears across RusttyObject.</p></div></div><div className="form-grid"><label className="modal-label">Workspace name<input className="modal-input" value="rusttyobject" readOnly /></label><label className="modal-label">Workspace slug<input className="modal-input" value="rusttyobject" readOnly /></label><label className="modal-label form-wide">Description<textarea className="modal-input textarea-input" defaultValue="GitHub-native object storage for the RusttyObject team." /></label></div></div><div className="panel settings-card"><div className="settings-card-heading"><div><h2>Default behavior</h2><p>Choose the defaults for new objects and buckets.</p></div></div><div className="setting-toggle-row"><span><strong>Automatic GitHub sync</strong><small>Push and pull object changes automatically.</small></span><Toggle checked={autoSync} onChange={setAutoSync} /></div><div className="setting-toggle-row"><span><strong>Protect main branch</strong><small>Require a sync check before writing to main.</small></span><Toggle checked={protectMain} onChange={setProtectMain} /></div><div className="setting-toggle-row"><span><strong>Public object links</strong><small>Allow sharing objects through public URLs.</small></span><Toggle checked={publicLinks} onChange={setPublicLinks} /></div></div></>}{settingsSection === 'GitHub connection' && <div className="panel settings-card"><div className="github-setting-banner"><span className="github-large"><Icon name="github" size={21} /></span><span><strong>rusttyobject</strong><small>Connected via GitHub App · installed just now</small></span><StatusPill tone="success">Connected</StatusPill></div><div className="setting-toggle-row"><span><strong>Webhook verification</strong><small>Verify every event with a signed GitHub payload.</small></span><Toggle checked={true} onChange={() => {}} /></div><div className="setting-toggle-row"><span><strong>Sync pull requests</strong><small>Index objects from pull request branches.</small></span><Toggle checked={false} onChange={() => {}} /></div><button className="danger-outline"><Icon name="close" size={14} /> Disconnect GitHub account</button></div>}{settingsSection === 'Sync rules' && <div className="panel settings-card"><div className="settings-card-heading"><div><h2>Sync rules</h2><p>Rules are evaluated in order from top to bottom.</p></div><button className="secondary-button"><Icon name="plus" size={14} /> Add rule</button></div>{['Ignore files larger than 100 MB', 'Include only media and data files', 'Skip generated preview folders'].map((rule, index) => <div className="rule-row" key={rule}><span className="rule-number">0{index + 1}</span><span><strong>{rule}</strong><small>{index === 0 ? 'size > 100MB' : index === 1 ? 'type in [image, video, json]' : 'path starts with /preview'}</small></span><StatusPill tone="success">Active</StatusPill><button className="row-more"><Icon name="more" size={17} /></button></div>)}</div>}{settingsSection === 'Access & tokens' && <div className="panel settings-card"><div className="settings-card-heading"><div><h2>Access tokens</h2><p>Use tokens to connect external clients to the RusttyObject API.</p></div><button className="primary-button"><Icon name="plus" size={14} /> Create token</button></div><div className="token-row"><span className="token-icon"><Icon name="terminal" size={15} /></span><span><strong>local-development</strong><small>Created Aug 12, 2026 · Last used 4 min ago</small></span><code>ro_live_••••••••7a2f</code><button className="copy-setting"><Icon name="copy" size={14} /></button><button className="row-more"><Icon name="more" size={17} /></button></div><div className="token-row"><span className="token-icon"><Icon name="terminal" size={15} /></span><span><strong>ci-deployments</strong><small>Created Jul 29, 2026 · Last used 1 hr ago</small></span><code>ro_live_••••••••c11b</code><button className="copy-setting"><Icon name="copy" size={14} /></button><button className="row-more"><Icon name="more" size={17} /></button></div></div>}{settingsSection === 'Usage & billing' && <div className="panel settings-card"><div className="billing-header"><div><span className="eyebrow compact-eyebrow">CURRENT PLAN</span><h2>Pro workspace</h2><p>50 GB storage · Unlimited queries · 5 team members</p></div><span className="plan-price">$24<span>/mo</span></span></div><div className="billing-meter"><div><span>Storage usage</span><strong>8.42 GB <small>/ 50 GB</small></strong></div><div className="billing-progress"><i /></div><small>16.8% used</small></div><div className="billing-footer"><span>Renews Sep 01, 2026</span><button className="secondary-button">Manage billing <Icon name="external" size={13} /></button></div></div>}</div></div>
  </div>
}

function App() {
  const [activeNav, setActiveNav] = useState('Overview')
  const [search, setSearch] = useState('')
  const [bucketFilter, setBucketFilter] = useState('All buckets')
  const [selectedObject, setSelectedObject] = useState(null)
  const [query, setQuery] = useState(queryExamples[0])
  const [queryRan, setQueryRan] = useState(false)
  const [showUpload, setShowUpload] = useState(false)
  const [mobileNav, setMobileNav] = useState(false)

  const filteredObjects = useMemo(() => objectData.filter((object) => {
    const matchesSearch = `${object.name} ${object.bucket} ${object.type}`.toLowerCase().includes(search.toLowerCase())
    const matchesBucket = bucketFilter === 'All buckets' || object.bucket === bucketFilter
    return matchesSearch && matchesBucket
  }), [search, bucketFilter])

  const runQuery = () => {
    setQueryRan(false)
    window.setTimeout(() => setQueryRan(true), 250)
  }

  return <div className="app-shell">
    <aside className={`sidebar ${mobileNav ? 'open' : ''}`}>
      <div className="sidebar-head"><Logo /><button className="mobile-close" onClick={() => setMobileNav(false)}><Icon name="close" size={18} /></button></div>
      <button className="workspace-switcher"><span className="workspace-avatar">R</span><span className="workspace-copy"><strong>rusttyobject</strong><small>main workspace</small></span><Icon name="down" size={15} /></button>
      <nav className="side-nav">
        <div className="nav-section-label">Workspace</div>
        {navItems.map((item) => <button key={item.label} className={`nav-item ${activeNav === item.label ? 'active' : ''}`} onClick={() => { setActiveNav(item.label); setMobileNav(false) }}><Icon name={item.icon} size={17} /><span>{item.label}</span>{item.count && <em>{item.count}</em>}{item.shortcut && <kbd>{item.shortcut}</kbd>}</button>)}
        <div className="nav-section-label system-label">System</div>
        <button className={`nav-item ${activeNav === 'Settings' ? 'active' : ''}`} onClick={() => { setActiveNav('Settings'); setMobileNav(false) }}><Icon name="settings" size={17} /><span>Settings</span></button>
      </nav>
      <div className="sidebar-bottom">
        <div className="sync-card"><div className="sync-card-row"><span className="github-small"><Icon name="github" size={14} /></span><span><strong>GitHub connected</strong><small>rusttyobject/storage</small></span><span className="live-dot" /></div><div className="sync-progress"><span /></div><div className="sync-foot"><span>Last sync</span><span>just now</span></div></div>
        <div className="user-row"><span className="user-avatar">AS</span><span><strong>Alex Smith</strong><small>Owner</small></span><Icon name="more" size={16} className="user-more" /></div>
      </div>
    </aside>

    <main className="main-content">
      <header className="topbar">
        <button className="mobile-menu" onClick={() => setMobileNav(true)}><Icon name="grid" size={20} /></button>
        <div className="breadcrumbs"><span>RusttyObject</span><Icon name="chevron" size={13} /><strong>{activeNav}</strong></div>
        <div className="topbar-actions"><div className="global-search"><Icon name="search" size={16} /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search objects..." /><kbd>⌘ K</kbd></div><button className="icon-button notification"><Icon name="bell" size={18} /><i /></button><button className="avatar-button">AS</button></div>
      </header>

      <div className={`page-wrap ${activeNav !== 'Overview' ? 'detail-mode' : ''}`}>
        <div className="overview-content">
        <div className="page-heading"><div><div className="eyebrow"><span className="eyebrow-line" /> WORKSPACE / MAIN</div><h1>Storage overview</h1><p>Everything your team stores, synced with GitHub and ready to query.</p></div><div className="heading-actions"><button className="secondary-button"><Icon name="clock" size={16} /> Last 30 days <Icon name="down" size={14} /></button><button className="primary-button" onClick={() => setShowUpload(true)}><Icon name="plus" size={17} /> New object</button></div></div>

        <section className="metrics-grid"><MetricCard label="Storage used" value="8.42 GB" detail="of 50 GB included" trend="12.8%" icon="activity" /><MetricCard label="Total objects" value="23,842" detail="across 3 buckets" trend="8.4%" icon="box" /><MetricCard label="Active buckets" value="03" detail="all systems nominal" trend="0.0%" direction="down" icon="grid" /><MetricCard label="Availability" value="99.99%" detail="last 30 days" trend="0.02%" icon="check" /></section>

        <section className="overview-grid"><article className="panel storage-panel"><div className="panel-heading"><div><h2>Storage used</h2><p>Daily repository usage over time</p></div><button className="more-button"><Icon name="more" size={18} /></button></div><StorageChart /></article><article className="panel activity-panel"><div className="panel-heading"><div><h2>Sync activity</h2><p>GitHub repository events</p></div><StatusPill tone="success">Live</StatusPill></div><div className="activity-total"><strong>1,284</strong><span>events this month</span><div className="activity-trend"><Icon name="arrowUp" size={13} /> 18.2%</div></div><div className="activity-bars"><div className="activity-axis"><span>300</span><span>200</span><span>100</span><span>0</span></div><div className="activity-plot"><div className="activity-grid"><i /><i /><i /><i /></div><div className="activity-columns">{[46, 54, 48, 65, 58, 73, 62, 80, 68, 88, 82, 96].map((value, index) => <span key={index} style={{ height: `${value}%` }}><b /></span>)}</div></div></div><div className="activity-labels"><span>Jun</span><span>Jul</span><span>Aug</span></div><div className="activity-footer"><span><i className="dot gray" /> Pulls <strong>704</strong></span><span><i className="dot black" /> Pushes <strong>580</strong></span></div></article></section>

        <section className="panel buckets-panel"><div className="panel-heading table-heading"><div><h2>Buckets</h2><p>Organize objects into isolated storage spaces</p></div><div className="table-actions"><button className="filter-button"><Icon name="filter" size={15} /> Filter</button><button className="square-button"><Icon name="more" size={17} /></button></div></div><div className="table-scroll"><table><thead><tr><th>Bucket name</th><th>Objects</th><th>Storage used</th><th>Last activity</th><th>Status</th><th /></tr></thead><tbody>{bucketData.map((bucket) => <tr key={bucket.name}><td><div className="bucket-cell"><BucketIcon tone={bucket.tone} /><span><strong>{bucket.name}</strong><small>{bucket.description}</small></span></div></td><td className="mono-cell">{bucket.objects}</td><td><div className="size-cell"><span>{bucket.size}</span><div className="tiny-progress"><i style={{ width: bucket.size === '4.8 GB' ? '74%' : bucket.size === '2.7 GB' ? '43%' : '18%' }} /></div></div></td><td className="muted-cell">{bucket.updated}</td><td><StatusPill tone={bucket.status === 'Synced' ? 'success' : 'warning'}>{bucket.status}</StatusPill></td><td><button className="row-more"><Icon name="more" size={17} /></button></td></tr>)}</tbody></table></div><button className="view-all" onClick={() => setActiveNav('Buckets')}>View all buckets <Icon name="arrowUp" size={14} /></button></section>

        <section className="panel objects-panel"><div className="panel-heading table-heading"><div><h2>Recent objects</h2><p>Latest files synced to your workspace</p></div><div className="object-controls"><select value={bucketFilter} onChange={(event) => setBucketFilter(event.target.value)}><option>All buckets</option>{bucketData.map((bucket) => <option key={bucket.name}>{bucket.name}</option>)}</select><button className="filter-button"><Icon name="filter" size={15} /> Filter</button></div></div><div className="table-scroll"><table><thead><tr><th>Object</th><th>Bucket</th><th>Type</th><th>Size</th><th>Updated</th><th /></tr></thead><tbody>{filteredObjects.map((object) => <tr className={selectedObject === object.name ? 'selected-row' : ''} key={object.name} onClick={() => setSelectedObject(object.name)}><td><div className="object-cell"><ObjectIcon type={object.icon} /><span><strong>{object.name}</strong><small>{object.hash}</small></span></div></td><td className="bucket-name-cell">{object.bucket}</td><td><span className="type-label">{object.type}</span></td><td className="mono-cell">{object.size}</td><td className="muted-cell">{object.updated}</td><td><button className="row-more" onClick={(event) => event.stopPropagation()}><Icon name="more" size={17} /></button></td></tr>)}{filteredObjects.length === 0 && <tr><td colSpan="6" className="empty-state">No objects match this search.</td></tr>}</tbody></table></div><button className="view-all">Browse object index <Icon name="arrowUp" size={14} /></button></section>

        <section className="console-shell"><div className="console-top"><div className="console-title"><span className="terminal-icon"><Icon name="terminal" size={17} /></span><div><h2>OQL terminal</h2><p>Query your object index with Object Query Language</p></div></div><div className="console-top-right"><StatusPill tone="dark">Connected to main</StatusPill><button className="console-expand" onClick={() => setActiveNav('OQL terminal')}><Icon name="external" size={15} /> Expand</button></div></div><div className="console-body"><div className="console-editor"><div className="editor-toolbar"><div className="editor-tab"><span className="tab-dot" /> query.oql <Icon name="close" size={12} /></div><span className="editor-hint">OQL v1.4</span></div><QueryEditor query={query} setQuery={setQuery} /><div className="editor-actions"><button className="run-button" onClick={runQuery}><Icon name="play" size={13} /> Run query <kbd>⌘ ↵</kbd></button><button className="copy-button" onClick={() => navigator.clipboard?.writeText(query)}><Icon name="copy" size={14} /> Copy</button></div></div><div className="console-output"><div className="output-head"><span>OUTPUT</span><span className="output-time">{queryRan ? 'Query completed in 42ms' : 'Ready'}</span></div>{queryRan ? <div className="query-result"><div className="result-success"><Icon name="check" size={14} /> 4 objects returned</div><div className="result-row"><span>hero-loop.mp4</span><span>18.4 MB</span></div><div className="result-row"><span>product-tour.mp4</span><span>32.1 MB</span></div></div> : <div className="output-placeholder"><span className="prompt">›</span><span>Run a query to see results here</span></div>}</div></div><div className="query-suggestions"><span>Try an example</span>{queryExamples.map((example, index) => <button key={example} onClick={() => setQuery(example)} className={query === example ? 'active' : ''}><span>0{index + 1}</span>{example}</button>)}</div></section>
        </div>
        {activeNav !== 'Overview' && <FeaturePage activeNav={activeNav} setActiveNav={setActiveNav} setShowUpload={setShowUpload} query={query} setQuery={setQuery} runQuery={runQuery} queryRan={queryRan} />}
      </div>
    </main>

    {showUpload && <div className="modal-backdrop" onClick={() => setShowUpload(false)}><div className="upload-modal" onClick={(event) => event.stopPropagation()}><div className="modal-head"><div><div className="modal-icon"><Icon name="upload" size={20} /></div><h2>New object</h2><p>Upload a file to your GitHub-backed store.</p></div><button className="modal-close" onClick={() => setShowUpload(false)}><Icon name="close" size={18} /></button></div><div className="dropzone"><div className="dropzone-icon"><Icon name="upload" size={22} /></div><strong>Drop an object here</strong><span>or click to browse from your computer</span><small>MP4, PNG, WEBM, JSON up to 100 MB</small></div><label className="modal-label">Destination bucket<select><option>media-production</option><option>design-assets</option><option>incoming-drops</option></select></label><div className="modal-actions"><button className="secondary-button" onClick={() => setShowUpload(false)}>Cancel</button><button className="primary-button" onClick={() => setShowUpload(false)}><Icon name="upload" size={16} /> Choose file</button></div></div></div>}
  </div>
}

createRoot(document.getElementById('root')).render(<React.StrictMode><App /></React.StrictMode>)
